suppressPackageStartupMessages({library(data.table);library(ggplot2)})
p='output/followup_analysis/';d=fread(paste0(p,'tables/metaintron_equal_shape_profiles.tsv'));fig=ggplot(d,aes(bin_index+.5,equal_intron_fraction,color=factor(construct),linetype=replicate))+geom_line()+facet_grid(assay~quartile)+theme_bw()+theme(legend.position='bottom')+labs(x='Intron position (%)',y='Mean within-intron read-density fraction per 1% bin',color='Construct',linetype='Replicate',title='Each supported intron contributes one total weight',subtitle='0 = all lengths; 1-4 = length quartiles; zero-support introns reported separately');for(e in c('png','pdf'))ggsave(paste0(p,'figures/metaintron_equal_shape.',e),fig,width=14,height=7,dpi=220)
d=fread(paste0(p,'tables/downsampling_spatial_iterations.tsv.gz'));fig=ggplot(d[iteration==0 & grepl('metaintron',profile)],aes(position,value,color=factor(construct),linetype=replicate))+geom_line()+facet_grid(assay~profile,scales='free_y')+theme_bw()+theme(legend.position='bottom')+labs(x='Intron position (%)',y='Mean depth per intron per million eligible reads',color='Construct',linetype='Replicate',title='Full-depth metaintron profiles: biological replicates');for(e in c('png','pdf'))ggsave(paste0(p,'figures/metaintron_read_quartiles.',e),fig,width=14,height=7,dpi=220)
